include { BEAGLE5_BEAGLE                          } from 'nf-core/beagle5/beagle'
include { BCFTOOLS_VIEW                           } from 'nf-core/bcftools/view'
include { GLIMPSE2_LIGATE                         } from 'nf-core/glimpse2/ligate'
include { BCFTOOLS_INDEX as BCFTOOLS_INDEX_PHASE  } from 'nf-core/bcftools/index'
include { BCFTOOLS_INDEX as BCFTOOLS_INDEX_LIGATE } from 'nf-core/bcftools/index'

workflow VCF_IMPUTE_BEAGLE5 {
    take:
    ch_input // channel (mandatory): [ [id], vcf, tbi ]
    ch_panel // channel (mandatory): [ [panel, chr], vcf, tbi ]
    ch_chunks // channel (optional) : [ [panel, chr], regionout ]
    ch_map // channel (optional) : [ [chr], map]

    main:

    // Branch input files based on format
    ch_input
        .branch { _meta, vcf, _tbi ->
            def vcfStr = vcf.toString()
            bcf: vcfStr.endsWith('.bcf') || vcfStr.endsWith('.bcf.gz')
            vcf: vcfStr.endsWith('.vcf') || vcfStr.endsWith('.vcf.gz')
            other: true
        }
        .set { ch_input_branched }

    ch_input_branched.other.map { _meta, vcf, _tbi ->
        error("ERROR: ${vcf.name} in ch_input channel must be in VCF or BCF format.")
    }

    // Convert BCF to VCF if necessary
    BCFTOOLS_VIEW(
        ch_input_branched.bcf,
        [],
        [],
        [],
    )

    // Combine VCF files
    ch_ready_vcf = ch_input_branched.vcf.mix(
        BCFTOOLS_VIEW.out.vcf.join(
            BCFTOOLS_VIEW.out.index,
            failOnMismatch: true,
            failOnDuplicate: true,
        )
    )

    // Prepare input channels for BEAGLE5 by combining VCF, panel, and map files
    ch_chunks_counts = ch_chunks
        .groupTuple()
        .map { metaPC, regionouts ->
            [metaPC, regionouts.size()]
        }

    ch_panel_map = ch_panel
        .combine(ch_map, by: 0)
        .combine(ch_chunks, by: 0)
        .combine(ch_chunks_counts, by: 0)

    ch_panel_map.ifEmpty {
        error("ERROR: join operation resulted in an empty channel. Please provide a valid ch_panel and ch_map channel as input.")
    }

    ch_beagle_input = ch_ready_vcf
        .combine(ch_panel_map)
        .map { metaI, input_vcf, input_index, metaPC, panel_vcf, panel_index, map, regionout, region_size ->
            def regionoutPadded
            if (regionout.contains(':')) {
                // Handle format like "chr22:1000-2000"
                def chr = regionout.tokenize(':')[0]
                def region = regionout.tokenize(':')[1]
                def start = region.tokenize('-')[0]
                def end = region.tokenize('-')[1]
                def paddedStart = String.format('%010d', start as long)
                def paddedEnd = String.format('%010d', end as long)
                regionoutPadded = "${chr}:${paddedStart}-${paddedEnd}"
            } else {
                // Handle format like "chr22" (no coordinates)
                regionoutPadded = regionout
            }
            [
                metaI + metaPC + ["regionout": regionout, "regionoutPadded": regionoutPadded, "regionSize": region_size],
                input_vcf,
                input_index,
                panel_vcf,
                panel_index,
                map,
                [],
                [],
                regionout,
            ]
        }

    // Run BEAGLE5 imputation
    BEAGLE5_BEAGLE(ch_beagle_input)

    // Index the imputed VCF files
    BCFTOOLS_INDEX_PHASE(BEAGLE5_BEAGLE.out.vcf)

    // Ligate all phased files in one and index it
    ligate_input = BEAGLE5_BEAGLE.out.vcf
        .join(
            BCFTOOLS_INDEX_PHASE.out.index,
            failOnMismatch: true,
            failOnDuplicate: true,
        )
        .map { meta, vcf, index ->
            def keysToKeep = meta.keySet() - ['regionout', 'regionoutPadded', 'regionSize']
            [
                groupKey(meta.subMap(keysToKeep), meta.regionSize),
                vcf, index,
            ]
        }
        .groupTuple()
        .map { groupKeyObj, vcf, index ->
            // Extract the actual meta from the groupKey
            def meta = groupKeyObj.getGroupTarget()
            [meta, vcf, index]
        }
        .branch { meta, vcf, index ->
            one: vcf.size() == 1
                return [meta, vcf.get(0), index.get(0)]
            more: vcf.size() > 1
                return [meta, vcf, index]
        }

    GLIMPSE2_LIGATE(ligate_input.more)

    BCFTOOLS_INDEX_LIGATE(GLIMPSE2_LIGATE.out.merged_variants)

    // Join imputed and index files
    ch_vcf_index = GLIMPSE2_LIGATE.out.merged_variants.join(
        BCFTOOLS_INDEX_LIGATE.out.index,
        failOnMismatch: true,
        failOnDuplicate: true,
    ).mix(
        ligate_input.one
    )

    emit:
    vcf_index = ch_vcf_index // channel: [ [id, chr, tools], vcf, index ]
}

nextflow_workflow {

    name "Test Subworkflow VCF_IMPUTE_BEAGLE5"
    script "../main.nf"
    workflow "VCF_IMPUTE_BEAGLE5"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/vcf_impute_beagle5"

    config "./nextflow.config"

    tag "beagle5"
    tag "beagle5/beagle"
    tag "bcftools"
    tag "bcftools/index"
    tag "bcftools/view"
    tag "glimpse2"
    tag "glimpse2/ligate"


    test("Impute with beagle5 one vcf - panel - whole chromosome - no map - one chromosomes") {
        when {
            workflow {
                """
                input[0] = Channel.of([
                    [id: "NA12878"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                ])
                input[1] = Channel.of([
                    [panel: "1000GP", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true)
                ])
                input[2] = Channel.of([[panel: "1000GP", chr: "chr22"], "chr22"]) // chunks
                input[3] = Channel.of([[panel: "1000GP", chr: "chr22"], []])
                """
            }
        }

        then {
            assert workflow.success
            assert snapshot(
                workflow.out.vcf_index.collect{[
                    it[0],
                    path(it[1]).getFileName().toString(),
                    path(it[2]).getFileName().toString(),
                    path(it[1]).vcf.summary,
                    path(it[1]).vcf.header.getGenotypeSamples().sort(),
                    path(it[1]).vcf.variantsMD5
                ]}
            ).match()
        }
    }

    test("Impute with beagle5 one bcf gz - panel - map - chunks - two chrosomes") {
        setup {
            run ("BCFTOOLS_VIEW", alias: "BCFTOOLS_VIEW_BCF" ) {
                script "../../../../modules/nf-core/bcftools/view"
                process {
                    """
                    input[0] = channel.of([
                        [id: "NA12878"],
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists:true),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                    ])
                    input[1] = []
                    input[2] = []
                    input[3] = []
                    """
                }
            }
        }
        when {
            params {
                bcftools_view_args = "--write-index=csi --output-type b"
            }
            workflow {
                """
                input[0] = BCFTOOLS_VIEW_BCF.out.vcf.join(BCFTOOLS_VIEW_BCF.out.index)
                input[1] = channel.of([
                    [panel: "1000GP", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true)
                ],[
                    [panel: "1000GP", chr: "chr21"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz.csi", checkIfExists:true)
                ])
                input[2] = channel.of(
                    [[chr: "chr22", panel: "1000GP"], "chr22:16570065-16592216"],
                    [[chr: "chr22", panel: "1000GP"], "chr22:16592229-16609999"],
                    [[chr: "chr21", panel: "1000GP"], "chr21:16570065-16592216"],
                    [[chr: "chr21", panel: "1000GP"], "chr21:16592229-16609999"]
                )
                input[3] = channel.of([
                    [panel: "1000GP", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.plink.map", checkIfExists:true)
                ],[
                    [panel: "1000GP", chr: "chr21"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr21.plink.map", checkIfExists:true)
                ])
                """
            }
        }

        then {
            assert workflow.success
            assert snapshot(
                workflow.out.vcf_index.collect{[
                    it[0].sort(),
                    path(it[1]).getFileName().toString(),
                    path(it[2]).getFileName().toString(),
                    path(it[1]).vcf.summary,
                    path(it[1]).vcf.header.getGenotypeSamples().sort(),
                    path(it[1]).vcf.variantsMD5
                ]}.sort{ it[1] }
            ).match()
        }
    }

    test("homo_sapiens - empty channels - stub") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([
                    [id: "NA12878"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                ])
                input[1] = channel.of(
                    [[panel: "1000GP", chr: "chr22"], [], []],
                    [[panel: "1000GP", chr: "chr21"], [], []]
                )
                input[2] = channel.of(
                    [[chr: "chr22", panel: "1000GP"], "chr22:16570065-16592216"],
                    [[chr: "chr22", panel: "1000GP"], "chr22:16592229-16609999"],
                    [[chr: "chr21", panel: "1000GP"], "chr21:16570065-16592216"],
                    [[chr: "chr21", panel: "1000GP"], "chr21:16592229-16609999"]
                )
                input[3] = channel.of(
                    [[panel: "1000GP", chr: "chr22"], []],
                    [[panel: "1000GP", chr: "chr21"], []]
                )
                """
            }
        }
        then {
            assert workflow.success
            assert snapshot(sanitizeOutput(workflow.out)).match()
        }
    }

    test("homo_sapiens - error wrong input format - stub") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([
                    [id: "NA12878"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.minimac.map", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                ])
                input[1] = channel.of(
                    [[panel: "1000GP", chr: "chr22"], [], []],
                    [[panel: "1000GP", chr: "chr21"], [], []]
                )
                input[2] = channel.of(
                    [[chr: "chr22", panel: "1000GP"], "chr22:16570065-16592216"],
                    [[chr: "chr22", panel: "1000GP"], "chr22:16592229-16609999"],
                    [[chr: "chr21", panel: "1000GP"], "chr21:16570065-16592216"],
                    [[chr: "chr21", panel: "1000GP"], "chr21:16592229-16609999"]
                )
                input[3] = channel.of(
                    [[panel: "1000GP", chr: "chr22"], []],
                    [[panel: "1000GP", chr: "chr21"], []]
                )
                """
            }
        }
        then {
            assert workflow.failed
            assert workflow.errorMessage.contains("ERROR: genome.GRCh38.chr22.minimac.map in ch_input channel must be in VCF or BCF format.")
        }
    }

    test("homo_sapiens - error empty joint - stub") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([
                    [id: "NA12878"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                ])
                input[1] = channel.of(
                    [[panel: "1000GP_1", chr: "chr22"], [], []], // Wrong panel
                    [[panel: "1000GP", chr: "chr21"], [], []]
                )
                input[2] = channel.of(
                    [[chr: "chr22", panel: "1000GP"], "chr22:16570065-16592216"],
                    [[chr: "chr22", panel: "1000GP"], "chr22:16592229-16609999"],
                    [[chr: "chr21", panel: "1000GP"], "chr21:16570065-16592216"],
                    [[chr: "chr21", panel: "1000GP"], "chr21:16592229-16609999"]
                )
                input[3] = channel.of(
                    [[panel: "1000GP", chr: "chr22"], []],
                    [[panel: "1000GP_1", chr: "chr21"], []] // Wrong panel
                )
                """
            }
        }
        then {
            assert workflow.failed
            assert workflow.errorMessage.contains("ERROR: join operation resulted in an empty channel. Please provide a valid ch_panel and ch_map channel as input.")
        }
    }
}

